def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    s = s.strip()
    s = s.replace("-final", "")
    if "b" in s:
        s = s.replace("b", ".0")
    if "rc" in s:
        s = s.replace("rc", "b")
    if "pre" in s:
        s = s.replace("pre", "b")
    nums = s.split(".")
    nums = [int(x) for x in nums]
    return tuple(nums)

