def namesAndDescriptions(self, all: bool = False):
    """Return attribute names and descriptions defined by interface."""
    interface_attrs = [attr[4:] for attr in dir(self.__class__.interface.__attrs__) if attr.startswith("inter")]
    names = [attr.replace("_", " ").capitalize() for attr in interface_attrs]
    descriptions = [getattr(self.interface.__attrs__, attr).__doc__ for attr in interface_attrs]
    if not all:
