def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory."""
    # Check if inventory is valid
    if not isinstance(inventory, dict):
        raise Exception("Inventory must be a dictionary")

    # Check if inventory has required fields
    required_fields = ["item_name", "amount", "price"]
    for field in required_fields:
        if field not in inventory:
            raise Exception(f"Inventory is missing required field: {field}")

    # Check if amount and price have correct datatypes
    for field, datatype in zip(["amount", "price"], [int, float]):
        if not isinstance(inventory[field], datatype):
            raise Exception(f"Inventory field '{field}' must be a {datatype.__name__}")

    # Check if inventory item name is valid
    item_name = inventory["item_name"]
    if not isinstance(item_name, str):
        raise Exception("Inventory item name must be a string")
    elif not item_name.isalpha():
        raise Exception("Inventory item name must only contain letters")

    # Return the inventory with the correct specification version
    spec_version = inventory.get("spec_version")
    if extract_spec_version and spec_version:
        return inventory
    elif spec_version != self.spec_version:
        raise Exception(f"Incorrect specification version: {spec_version}")
    else:
        inventory["spec_version"] = self.spec_version
        return inventory

