def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    # Check that fixity is a list
    if not isinstance(fixity, list):
        raise TypeError("Fixity is not a list")

    # Check that fixity is not empty
    if not fixity:
        raise ValueError("Fixity block is empty")

    # Check that fixity block contains elements of the correct format
    if any(not isinstance(fix, dict) or "URI" not in fix for fix in fixity):
        raise ValueError("Fixity block contains elements that are not of the correct format")

    # Check that all the files referenced in the fixity block are in the manifest
    fixity_files = {fix["URI"] for fix in fixity}
    missing_files = fixity_files - set(manifest_files)
    if missing_files:
        raise ValueError("Fixity block references files not in the manifest:", missing_files)

