def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    results = []
    for arg in args:
        if arg == "A":
            results.append("A")
        elif "(" in arg:
            parts = arg.split("|")
            if len(parts) == 2:
                a, b = parts
                a = a.strip()
                b = b.strip()
                if a == "A":
                    results.append(f"A & {b}")
                elif b == "A":
                    results.append(f"A | {a}")
                else:
                    results.append(f"{a} | {b}")
            else:
                parts = arg.split("&")
                if len(parts) == 2:
                    a, b = parts
                    a = a.strip()
                    b = b.strip()
                    if a == "A":
                        results.append(f"A & {b}")
                    elif b == "A":
                        results.append(f"A | {a}")
                    else:
                        results.append(f"{a} & {b}")
                else:
                    results.append(arg)
        else:
            results.append(arg)
    return results

