def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: The command(s) to run
    :type commands: str or list
    :param args: The arguments for the command(s)
    :type args: list
    :param cwd: The working directory for running the command(s)
    :type cwd: str
    :param verbose: Whether to print verbose output
    :type verbose: bool
    :param hide_stderr: Whether to hide stderr
    :type hide_stderr: bool
    :param env: Environment variables to pass to the command(s)
    :type env: dict
    """

    if isinstance(commands, str):
        commands = [commands]

    for command in commands:
        if cwd:
            cwd = os.path.expanduser(cwd)
            if not os.path.exists(cwd):
                raise FileNotFoundError(f"Directory {cwd} doesn't exist")
        else:
            cwd = None

        if env:
            env = {k: os.path.expandvars(v) for k, v in env.items()}
        else:
            env = None

        try:
            if verbose:
                print(f"Running command '{command} {args}'")
            proc = subprocess.Popen([command, *args], cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
            output, stderr = proc.communicate()
        except subprocess.CalledProcessError:
            msg = f"Failed to run command '{command} {args}'"
            raise ProgramError(msg)

        if hide_stderr:
            stderr = None

        if verbose:
            print(f"Command output:\n{output.decode()}")

        if stderr:
            print(f"Command stderr:\n{stderr.decode()}")

    return output.decode()

