        return None
    match = re.match(r"(\d+) (\w+)", frequency)
    if not match:
        raise ValueError("Invalid frequency string")
    # Parse the frequency
    num, unit = match.group(1), match.group(2)
    # Map the unit to the corresponding keyword argument for datetime.timedelta
    kwargs = {"days": "days", "weeks": "weeks", "months": "months", "years": "years"}.get(unit)
    if not kwargs:
        raise ValueError("Invalid unit of time")
    # Return a datetime.timedelta instance
    return datetime.timedelta(**{kwargs: int(num)})

