def verifyClass(iface, candidate, tentative=False):
    if not iface:
        raise ValueError("Interface cannot be empty")
    if not candidate:
        raise ValueError("Candidate cannot be empty")
    if not tentative:
        iface.verify(candidate)
    else:
        if iface.type() == "duck" and candidate.type() == "duck":
            return True
        else:
            return False
    if iface.methods:  # assess method exportation
        for method in iface.methods:
            if method not in candidate.methods:
                return False
            if not tentative:
                iface.verify(candidate.methods[method])
            else:
                if candidate.methods[method](1) != 1:
                    return False
    else:  # no methods, simply return True
        return True

