def determineMetaclass(bases, explicit_mc=None):
    """Return metaclass for given bases and explicit __metaclass__

    :param bases: Sequence of base classes
    :type bases: sequence of types
    :param explicit_mc: Explicit metaclass, defaults to None
    :type explicit_mc: type or None
    :returns: Metaclass for bases and explicit __metaclass__
    :rtype: type
    """
    # Check if explicit metaclass is passed or defined
    if explicit_mc is None:
        for base in bases:
            try:
                for mc in base.__metaclass__:
                    return mc
            except AttributeError:
                continue
        # If no explicit metaclass found, return type(top ancestor)
        return type(bases[0])
    else:
        # Explicit metaclass is passed, return it
        return explicit_mc

