def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("expected type of args to be dict, got {}".format(type(args).__name__))
    for key, value in args.items():
        # check if value is between min and max
        if not (self.min <= value <= self.max):
            raise ValueError("{} is not between the allowed minimum and maximum values".format(value))
    return args

