def _convert_non_cli_args( parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if parser_name in ['main', 'virsh', 'ospd']:
        for key in values_dict.keys():
            if key.endswith('_host'):
                values_dict[key] = values_dict[key].strip()
                if values_dict[key][0] == '/':
                    values_dict[key] = values_dict[key][1:]
            elif key == 'debug_port':
                values_dict[key] = int( values_dict[key])
            elif key == 'ka_port':
                values_dict[key] = int(values_dict[key])
    return values_dict

